/* @lc app=leetcode id=3964 lang=kotlin */ class Solution { fun minLights(lights: IntArray): Int = lights.size.let { n -> IntArray(n + 1).also { d -> lights.indices.filter { lights[it] > 0 }.forEach { i -> d.set(maxOf(0, i - lights[i]), d[maxOf(0, i - lights[i])] + 1).also { d[minOf(n - 1, i + lights[i]) + 1]-- } } }.runningFold(0) { a, b -> a + b }.drop(1).let { cv -> (0 until n).fold(-1 to 0) { (last, cnt), i -> if (cv[i] > 0 || i <= last) last to cnt else (i + 2) to cnt + 1 }.second } } }